import type { ComponentProps } from "react";

import "./empty.css";

/**
 * Empty, opencode console's empty list state with shadcn's part names. There
 * is no behaviour, so the parts are plain markup styled by `empty.css`. Pass
 * `role="status"` to Empty when it replaces a list after a user action.
 */

export function Empty(props: ComponentProps<"div">) {
  return <div {...props} data-slot="empty" />;
}

export function EmptyHeader(props: ComponentProps<"div">) {
  return <div {...props} data-slot="empty-header" />;
}

export type EmptyMediaVariant = "default" | "icon";

export function EmptyMedia({
  variant = "default",
  ...props
}: ComponentProps<"div"> & { variant?: EmptyMediaVariant }) {
  return <div {...props} data-slot="empty-media" data-variant={variant} />;
}

export function EmptyTitle(props: ComponentProps<"p">) {
  return <p {...props} data-slot="empty-title" />;
}

export function EmptyDescription(props: ComponentProps<"p">) {
  return <p {...props} data-slot="empty-description" />;
}

export function EmptyContent(props: ComponentProps<"div">) {
  return <div {...props} data-slot="empty-content" />;
}

/*
 * Empty, ported from opencode console's empty list state (`.control-empty`,
 * the "nothing here yet" panel on the console's control lists, read from its
 * live stylesheet; the console's source is not in the opencode checkout). The
 * rules are the console's, with the selectors renamed to Kitsaas slots:
 *
 *   .control-empty                          →  [data-slot="empty"]
 *   .control-empty-content                  →  [data-slot="empty-header"]
 *   .control-empty-text                     →  (no wrapper; see below)
 *   .control-empty p                        →  empty-title / empty-description
 *   .control-empty [data-component="button-v2"]  →  a [data-slot="button"] in it
 *   .control-list-icon (≤760px, extensions) →  empty-media[data-variant="icon"]
 *
 * `.control-empty` sets no colours or weights for its text, so those come from
 * the console's other empty states:
 *
 *   title weight 530    .policy-members-empty p:first-child (console builder)
 *   title colour, description colour, letter-spacing, 360px description
 *   measure and the muted icon colour:
 *     session-ui v2's empty review panel (packages/session-ui/src/v2/
 *     components/session-review-v2.css, `session-review-v2-empty-no-git-*`)
 *
 * Every token is already --v2-*, so there is no --oc-* or legacy mapping.
 *
 * Kitsaas additions, marked below: shadcn puts EmptyMedia, EmptyTitle and
 * EmptyDescription straight in EmptyHeader, so the console's 8px icon-to-text
 * gap and 4px title-to-description gap become a 4px header gap plus 4px under
 * the media; EmptyContent (shadcn's action row) is a centred 8px-gap flex row;
 * `margin: 0` on the text, since Kitsaas does not rely on preflight inside
 * components; and the default media's 20px icon size.
 */

@layer components {
  [data-slot="empty"] {
    box-sizing: border-box;
    background: var(--v2-background-bg-layer-01);
    min-height: 200px;
    box-shadow: inset 0 0 0 0.5px var(--v2-border-border-muted);
    text-align: center;
    border-radius: 6px;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 16px;
    padding: 32px;
    display: flex;
    min-width: 0;
    color: var(--v2-text-text-base);
    font-family: var(--v2-font-family-sans, inherit);
  }

  [data-slot="empty-header"] {
    flex-direction: column;
    align-items: center;
    /* Kitsaas: .control-empty-text's 4px, since there is no text wrapper. */
    gap: 4px;
    display: flex;
  }

  [data-slot="empty-title"],
  [data-slot="empty-description"] {
    margin: 0; /* Kitsaas */
    font-size: 13px;
    line-height: 20px;
    letter-spacing: -0.04px;
  }

  [data-slot="empty-title"] {
    font-weight: 530;
    color: var(--v2-text-text-base);
  }

  [data-slot="empty-description"] {
    max-width: 360px;
    font-weight: 440;
    color: var(--v2-text-text-muted);
    text-wrap: pretty;
  }

  [data-slot="empty-description"] a {
    color: inherit;
    text-decoration: underline;
    text-underline-offset: 2px;
  }

  [data-slot="empty-description"] a:hover {
    color: var(--v2-text-text-base);
  }

  [data-slot="empty-media"] {
    flex: none;
    justify-content: center;
    align-items: center;
    display: flex;
    color: var(--v2-icon-icon-muted);
    /* Kitsaas: with .control-empty-text's 4px, the console's 8px to the text. */
    margin-bottom: 4px;
  }

  /* Kitsaas: the session-ui empty panel's 20px icon. */
  [data-slot="empty-media"][data-variant="default"] > svg {
    width: 20px;
    height: 20px;
  }

  /* The console's raised icon tile, at its 32px extensions size. */
  [data-slot="empty-media"][data-variant="icon"] {
    background: var(--v2-background-bg-base);
    width: 32px;
    height: 32px;
    box-shadow: var(--v2-elevation-raised);
    border-radius: 6px;
  }

  [data-slot="empty-media"][data-variant="icon"] > svg {
    width: 16px;
    height: 16px;
  }

  /* Kitsaas: shadcn's action row. */
  [data-slot="empty-content"] {
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 8px;
    display: flex;
    min-width: 0;
    max-width: 100%;
  }

  [data-slot="empty"] [data-slot="button"] {
    height: 24px;
  }
}
